// TypeMorph - Memory Dump Fixer & Dynamic PE Reconstructor (vmpdump / WriteProcess-Dumper / Scylla)
//
// Reconstructs dumped memory images into valid, runnable Windows Portable Executable (PE) files:
// - Virtual Memory to Raw File Offset alignment: aligns section headers with VirtualAddress / SizeOfRawData.
// - PE Header Sanitization: restores DosHeader, NtHeaders, SectionHeaders from virtual memory artifacts.
// - Unpack memory dumps generated by WriteProcessMemory, Process Hacker, Scylla, or vmpdump.
// - Entry Point & Import Table verification.
#pragma once

#include "typemorph/core/binary_view.hpp"

#include <cstdint>
#include <string>
#include <vector>

namespace typemorph::dump {

using core::BinaryView;

struct DumpSectionInfo {
    std::string name;
    std::uint32_t virtual_address = 0;
    std::uint32_t virtual_size = 0;
    std::uint32_t raw_data_offset = 0;
    std::uint32_t raw_data_size = 0;
    std::uint32_t characteristics = 0;
    bool is_executable = false;
    bool is_writable = false;
};

struct DumpFixReport {
    bool is_memory_dump = false;
    std::string detected_source; // "vmpdump", "WriteProcess-Dumper", "Generic Virtual Memory Dump"
    std::uint64_t image_base = 0x00400000;
    std::uint32_t original_entry_point_rva = 0;
    std::uint32_t file_alignment = 0x200;
    std::uint32_t section_alignment = 0x1000;
    std::vector<DumpSectionInfo> sections;
    std::size_t total_sections = 0;
    bool headers_rebuilt = false;
    std::vector<std::string> log;
};

struct DumpFixResult {
    bool success = false;
    DumpFixReport report;
    std::vector<std::uint8_t> fixed_pe_image;
    std::string error_message;
};

class DumpFixer {
public:
    static bool is_memory_dump(const BinaryView& view);
    static DumpFixReport analyze(const BinaryView& view);
    static DumpFixResult fix(const BinaryView& view, std::uint64_t new_oep_va = 0);
    static std::string format_report(const DumpFixReport& report);
};

} // namespace typemorph::dump
